def parse_rows(raw):
    result=[]
    for line in raw.strip().splitlines():
        parts=line.split('|')
        if len(parts)!=len(FIELDS):
            raise ValueError((parts[0],len(parts)))
        result.append(dict(zip(FIELDS,parts)))
    return result

PROFILES = parse_rows(ROWS)
